import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen5Test {

    @Test
    public void testFormatWithDefaultInstance() {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Date date = new Date(1234567890000L); // 2009-02-13
        String result = fdf.format(date);
        assertEquals("2009-02-13", result);
    }

    @Test
    public void testFormatWithSpecificPatternAndTimeZone() {
        TimeZone tz = TimeZone.getTimeZone("GMT");
        FastDateFormat fdf = FastDateFormat.getInstance("HH:mm:ss", tz);
        // 12:34:56 GMT
        Date date = new Date(1234567890000L); 
        // Adjusting date to match a specific time for predictability
        Calendar cal = Calendar.getInstance(tz);
        cal.set(2023, Calendar.JANUARY, 1, 12, 34, 56);
        cal.set(Calendar.MILLISECOND, 0);
        Date specificDate = cal.getTime();

        String result = fdf.format(specificDate);
        assertEquals("12:34:56", result);
    }

    @Test
    public void testFormatWithLocale() {
        // Using French locale to test potential locale-specific formatting if pattern involves month names
        FastDateFormat fdf = FastDateFormat.getInstance("MMMM", Locale.FRENCH);
        Calendar cal = Calendar.getInstance(Locale.FRENCH);
        cal.set(2023, Calendar.MAY, 1);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // "mai" is May in French
        assertEquals("mai", result.toLowerCase());
    }

    @Test
    public void testFormatWithDateStyleInstance() {
        FastDateFormat fdf = FastDateFormat.getDateInstance(Calendar.LONG, Calendar.SHORT);
        Date date = new Date(1234567890000L);
        String result = fdf.format(date);
        assertNotNull(result);
        // Result depends on system default locale, but should not be null/empty
        assert(result.length() > 0);
    }

    @Test
    public void testFormatWithDateTimeStyleInstance() {
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(Calendar.MEDIUM, Calendar.MEDIUM);
        Date date = new Date();
        String result = fdf.format(date);
        assertNotNull(result);
        assert(result.length() > 0);
    }

    @Test
    public void testFormatWithMillisecondPrecision() {
        FastDateFormat fdf = FastDateFormat.getInstance("SSS");
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.MILLISECOND, 123);
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("123", result);
    }

    @Test
    public void testFormatWithZeroPadding() {
        FastDateFormat fdf = FastDateFormat.getInstance("MM");
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.MONTH, Calendar.JANUARY); // Month is 0-indexed
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("01", result);
    }

    @Test
    public void testFormatWithLargeDate() {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        // Year 9999
        Calendar cal = Calendar.getInstance();
        cal.set(9999, 0, 1);
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("9999", result);
    }
}
